import { tokens } from "@/entities/data/tokens";
import type { Token } from "@/entities/data/types";
import { indexBy } from "@/entities/lookup/indexBy";

const tokensMap = indexBy(tokens, (token) => token.id);

export type OneWayDirection = "in" | "out";

export type OneWayWormholeToken = {
  baseId: string;
  direction: OneWayDirection;
};

const ONE_WAY_SUFFIX = /^(.+)_(in|out)$/;

/**
 * One-way wormhole tokens ("whalpha_in", "whbeta_out", ...) are generated by
 * the bot from the plain single-wormhole tokens rather than listed in the
 * token data, and drawn as the base token with an entry/exit ring.
 */
export const getOneWayWormholeToken = (
  tokenId: string,
): OneWayWormholeToken | undefined => {
  if (tokensMap.has(tokenId)) return undefined;
  const match = ONE_WAY_SUFFIX.exec(tokenId);
  if (!match) return undefined;
  const base = tokensMap.get(match[1]);
  if (base?.wormholes?.length !== 1) return undefined;
  return { baseId: base.id, direction: match[2] as OneWayDirection };
};

const oneWayTokenData = (tokenId: string): Token | undefined => {
  const oneWay = getOneWayWormholeToken(tokenId);
  if (!oneWay) return undefined;
  const base = tokensMap.get(oneWay.baseId)!;
  return { ...base, id: tokenId, aliasList: undefined };
};

export const getTokenData = (tokenId: string) =>
  tokensMap.get(tokenId) ?? oneWayTokenData(tokenId);

export const getTokenImagePath = (tokenId: string): string | null => {
  const tokenData = getTokenData(tokenId);
  if (!tokenData) return null;
  return `/tokens/${tokenData.imagePath}`;
};
